urlset:
{%- for sitemap_entry in entries %}
{%- if not (sitemap_entry.permalink is ending_with("/page/1/")) %}

    {{ sitemap_entry.permalink | escape_xml | safe }}
    {%- if sitemap_entry.updated %}
    {{ sitemap_entry.updated }}
    {%- endif %}
    {%- if sitemap_entry.extra and sitemap_entry.extra.sitemap_priority %}
    {{ sitemap_entry.extra.sitemap_priority }}
    {%- endif %}

{%- endif %}
{%- endfor %}
